using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    // Bronze customer is charged the subtotal less the Bronze reduction
    [Theory]
    [InlineData(10000, 9500)]
    [InlineData(7, 7)]
    public void Bronze_customer_is_charged_the_subtotal_less_the_Bronze_reduction(
        int subtotalCents, int expectedChargedCents)
    {
        var calculateLoyaltyDiscount = new CalculateLoyaltyDiscount();

        var quote = calculateLoyaltyDiscount.Handle(
            new CalculateLoyaltyDiscountQuery(subtotalCents, LoyaltyTier.Bronze));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}

